// 統合辞書を構築する
const DICTIONARY = {};
function addDictEntry(word, meaningJP, partOfSpeech, extra) {
  const key = norm(word);
  if (!key || DICTIONARY[key]) return;
  DICTIONARY[key] = Object.assign(
    { word, meaningJP, partOfSpeech: partOfSpeech || "" },
    extra || {},
  );
}
for (const q of [...QUESTION_BANK, ...A2_EXTRA_QUESTION_BANK, ...B1_QUESTION_BANK, ...B2_QUESTION_BANK]) {
  for (const v of q.vocabulary) {
    addDictEntry(v.word, v.meaningJP, v.partOfSpeech, {
      explanationJP: v.explanationJP, example: v.example, exampleJP: v.exampleJP,
    });
  }
  for (const c of q.collocations || []) addDictEntry(c.expression, c.meaningJP, "表現");
  for (const c of q.choices) {
    const exp = q.choiceExplanations.find((e) => e.choice === c.id);
    const m = exp && exp.explanationJP.match(/[＝=]\s*([^。]+)/);
    if (m) addDictEntry(c.text, m[1].trim(), "");
  }
}

// 現在のレベルに応じた語彙クイズバンク
function activeQuestionBank() {
  const level = currentLevel();
  if (level === "B2") return B2_QUESTION_BANK;
  if (level === "B1") return B1_QUESTION_BANK;
  return [...QUESTION_BANK, ...A2_EXTRA_QUESTION_BANK];
}

// レベル別バンクの共通セレクタ（会話・読解などで使用）
function pickBankByLevel(banks) {
  return banks[currentLevel()] || banks.A2;
}
for (const [word, value] of Object.entries(SUPPLEMENT_DICT)) {
  if (Array.isArray(value)) addDictEntry(word, value[0], value[1]);
  else addDictEntry(word, value, "");
}

function lookupWord(word) {
  return DICTIONARY[norm(word)] || null;
}

/* ---------------------------------------------------------------------------
   発音再生（Web Speech API）
   ブラウザ内蔵のベトナム語音声（vi-VN）を使用する。外部APIは不要。
--------------------------------------------------------------------------- */
let viVoice = null;

function pickVietnameseVoice() {
  if (!("speechSynthesis" in window)) return;
  const voices = speechSynthesis.getVoices();
  viVoice =
    voices.find((v) => v.lang.toLowerCase().replace("_", "-").startsWith("vi")) || null;
}
if ("speechSynthesis" in window) {
  pickVietnameseVoice();
  speechSynthesis.onvoiceschanged = pickVietnameseVoice;
}

// 再生速度の設定（全ての音声で共通・localStorageに保存）
const SPEED_OPTIONS = [
  { key: "slow", label: "遅い", rate: 0.65 },
  { key: "normal", label: "普通", rate: 0.85 },
  { key: "fast", label: "速い", rate: 1.05 },
];

function currentSpeedKey() {
  return SPEED_OPTIONS.some((o) => o.key === store.speechSpeed)
    ? store.speechSpeed
    : "normal";
}
function currentRate() {
  return SPEED_OPTIONS.find((o) => o.key === currentSpeedKey()).rate;
}

// ページ内すべての速度切り替えUI（[data-speed-control]）を描画・同期する
function renderSpeedControls() {
  const active = currentSpeedKey();
  document.querySelectorAll("[data-speed-control]").forEach((el) => {
    el.innerHTML = SPEED_OPTIONS.map(
      (o) =>
        `<button type="button" data-speed="${o.key}" class="${o.key === active ? "active" : ""}">${o.label}</button>`,
    ).join("");
  });
}
document.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-speed]");
  if (!btn) return;
  store.speechSpeed = btn.dataset.speed;
  saveStore();
  renderSpeedControls();
});

// テキストを読み上げる。button指定時は再生中の見た目に切り替える。
function speak(text, button) {
  if (!("speechSynthesis" in window) || !text) return;
  speechSynthesis.cancel();
  const utterance = new SpeechSynthesisUtterance(text);
  utterance.lang = "vi-VN";
  if (viVoice) utterance.voice = viVoice;
  utterance.rate = currentRate(); // 速度切り替え（遅い/普通/速い）に連動
  if (button) {
    button.classList.add("speaking");
    const done = () => button.classList.remove("speaking");
    utterance.onend = done;
    utterance.onerror = done;
  }
  speechSynthesis.speak(utterance);
}

/* ---------------------------------------------------------------------------
   簡易SRS（CLAUDE.md セクション18準拠の簡略版）
--------------------------------------------------------------------------- */
const INTERVAL_DAYS = { new: 1, forgotten: 1, unsure: 2, learning: 3, reviewing: 5, mastered: 14 };
const LADDER = [1, 3, 7, 14, 30];

function nextReviewAt(status, consecutiveCorrect) {
  let days = INTERVAL_DAYS[status] || 1;
  if (consecutiveCorrect > 0 && status !== "forgotten" && status !== "unsure") {
    days = LADDER[Math.min(consecutiveCorrect - 1, LADDER.length - 1)];
    if (status === "mastered") days = Math.max(days, 14);
  }
  return new Date(Date.now() + days * DAY_MS).toISOString();
}

const clampScore = (s) => Math.max(0, Math.min(100, Math.round(s)));

// 語彙イベント適用：カウント・status・masteryScore・次回復習日を更新する
// 一度の正解で mastered にしない（score>=80 かつ 3連続正解が条件）
function applyVocabEvent(v, kind) {
  const deltas = { quizCorrect: 10, quizWrong: -15, remembered: 8, unsure: -3, forgotten: -12 };
  v.masteryScore = clampScore((v.masteryScore || 0) + (deltas[kind] || 0));

  const correct = kind === "quizCorrect" || kind === "remembered";
  const wrong = kind === "quizWrong" || kind === "forgotten";
  if (correct) { v.consecutiveCorrect = (v.consecutiveCorrect || 0) + 1; v.consecutiveWrong = 0; }
  if (wrong) { v.consecutiveWrong = (v.consecutiveWrong || 0) + 1; v.consecutiveCorrect = 0; v.wrongCount = (v.wrongCount || 0) + 1; }

  if (wrong) {
    v.status = v.status === "mastered" ? "reviewing" : "forgotten";
  } else if (kind === "unsure") {
    v.status = "unsure";
  } else if (correct) {
    const mastered = v.masteryScore >= 80 && v.consecutiveCorrect >= 3;
    v.status = mastered ? "mastered" : v.status === "new" ? "learning" : "reviewing";
  }

  v.lastReviewedAt = nowIso();
  v.nextReviewAt = nextReviewAt(v.status, v.consecutiveCorrect || 0);
}

// 問題から学習価値のある語彙を保存する（target優先、既存はexposure更新）
function upsertVocabFromQuestion(q, isCorrect) {
  const targetKey = norm(q.targetVocabulary);
  for (const entry of q.vocabulary) {
    const key = norm(entry.word);
    let v = store.vocab[key];
    if (!v) {
      v = store.vocab[key] = {
        word: entry.word, meaningJP: entry.meaningJP, partOfSpeech: entry.partOfSpeech,
        example: entry.example || (key === targetKey ? q.sentence.replace(/_{2,}/, q.targetVocabulary) : ""),
        exampleJP: entry.exampleJP || (key === targetKey ? q.translationJP : ""),
        collocations: key === targetKey ? (q.collocations || []) : [],
        status: "new", masteryScore: 0, exposureCount: 0,
        consecutiveCorrect: 0, consecutiveWrong: 0, wrongCount: 0,
        firstSeenAt: nowIso(), nextReviewAt: nextReviewAt("new", 0),
      };
    }
    v.exposureCount = (v.exposureCount || 0) + 1;
    if (key === targetKey) applyVocabEvent(v, isCorrect ? "quizCorrect" : "quizWrong");
  }
}

/* ---------------------------------------------------------------------------
   画面制御
--------------------------------------------------------------------------- */
const $ = (id) => document.getElementById(id);
const SCREENS = ["home", "quiz", "result", "flashcards", "fc-done", "history", "analysis", "listening", "situation", "passage", "reading", "builder", "sentlisten", "mixedresult"];

function showScreen(name) {
  for (const s of SCREENS) $("screen-" + s).classList.add("hidden");
  $("screen-" + name).classList.remove("hidden");
  window.scrollTo(0, 0);
  // ホームへ戻ったらミックス練習を中断扱いにする（次の単独練習の完了を乗っ取らないため）
  if (name === "home") mixed.active = false;
  if (name === "home") renderHome();
  if (name === "history") renderHistory();
  if (name === "analysis") renderAnalysis();
}

function escapeHtml(text) {
  const div = document.createElement("div");
  div.textContent = text;
  return div.innerHTML;
}

/* ---------------------------------------------------------------------------
   ホーム画面
--------------------------------------------------------------------------- */
function dueVocabList() {
  const now = nowIso();
  return Object.values(store.vocab).filter(
    (v) => v.status === "forgotten" || v.status === "unsure" || (v.nextReviewAt && v.nextReviewAt <= now),
  );
}

function streakDays() {
  const days = Object.keys(store.days).sort().reverse();
  if (days.length === 0) return 0;
  if (days[0] !== todayStr() && days[0] !== todayStr(1)) return 0;
  let streak = 1;
  for (let i = 1; i < days.length; i++) {
    const prev = new Date(days[i - 1]).getTime();
    const cur = new Date(days[i]).getTime();
    if (Math.round((prev - cur) / DAY_MS) === 1) streak++;
    else break;
  }
  return streak;
}

/* ---------------------------------------------------------------------------
   練習の進捗（解いた数 / 総数）
   各練習タイプについて「今のレベルで出題されうる問題数」と「これまでに解いた数」を
   数え、ホームのボタンと各練習画面の進捗行に表示する。
   解答の記録は各タイプの answer 系関数から markPracticeDone() を呼んで行う。
   （ミックス練習も同じ answer 関数を通るため、そのまま数えられる）
--------------------------------------------------------------------------- */

// 問題を識別する短いキー（FNV-1a 32bit）。問題文をそのまま保存すると
// localStorageが膨らむため、8桁の16進に畳んで保存する。
function hashKey(text) {
  let h = 0x811c9dc5;
  const s = String(text);
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, "0");
}

// 今のレベルで出題されうる全問題のキー（記録側と同じ文字列から作ること）
function practiceItemKeys(type) {
  switch (type) {
    case "quiz":
      return activeQuestionBank().map((q) => q.sentence);
    case "listening":
      return listeningAnswerPool().map((e) => norm(e.word));
    case "situation":
      return pickBankByLevel({ A2: SITUATION_BANK, B1: B1_SITUATION_BANK, B2: B2_SITUATION_BANK }).map((q) => q.t);
    case "passage":
      // 空欄1つを1問として数える
      return pickBankByLevel({ A2: PASSAGE_BANK, B1: B1_PASSAGE_BANK, B2: B2_PASSAGE_BANK })
        .flatMap((p) => p.blanks.map((_, i) => p.text + "#" + i));
    case "reading":
      return pickBankByLevel({ A2: READING_BANK, B1: B1_READING_BANK, B2: B2_READING_BANK })
        .flatMap((r) => r.questions.map((_, i) => r.text + "#" + i));
    case "builder":
      return pickBankByLevel({ A2: BUILDER_BANK, B1: B1_BUILDER_BANK, B2: B2_BUILDER_BANK }).map((q) => builderKey(q.w));
    case "sentlisten":
      return sentListenBank().map((q) => q.sentence);
    default:
      return [];
  }
}

// 1問解いたことを記録する。表示もその場で更新する（画面上の「累計」が即座に増える）
function markPracticeDone(type, rawKey) {
  if (!PRACTICE_TYPES.includes(type)) return;
  if (!store.progress[type]) store.progress[type] = {};
  store.progress[type][hashKey(rawKey)] = 1;
  renderPracticeProgress();
}

// 今のレベルでの { 解いた数, 総数 }
function practiceStats(type) {
  const done = store.progress[type] || {};
  const keys = practiceItemKeys(type);
  let count = 0;
  for (const key of keys) if (done[hashKey(key)]) count++;
  return { done: count, total: keys.length };
}

// ホームのボタンと各練習画面の進捗行をまとめて更新する
function renderPracticeProgress() {
  let doneAll = 0;
  let totalAll = 0;
  for (const type of PRACTICE_TYPES) {
    const { done, total } = practiceStats(type);
    doneAll += done;
    totalAll += total;

    const btn = $("cnt-" + type);
    if (btn) btn.textContent = `${done}/${total}問`;

    const row = $("lp-" + type);
    if (row) row.textContent = `${done}/${total}問`;
  }
  // ミックス練習は全タイプから出題するため、合計を出す
  const mixedCount = $("cnt-mixed");
  if (mixedCount) mixedCount.textContent = `${doneAll}/${totalAll}問`;
}

function renderHome() {
  const today = store.days[todayStr()] || { questions: 0, correct: 0 };
  $("stat-today-questions").textContent = today.questions + "問";
  $("stat-today-accuracy").textContent =
    today.questions > 0 ? Math.round((today.correct / today.questions) * 100) + "%" : "—";
  $("stat-vocab-total").textContent = Object.keys(store.vocab).length + "語";

  const due = dueVocabList().length;
  $("stat-due").textContent = due + "語";
  $("due-count").textContent = due;

  const streak = streakDays();
  $("streak-badge").classList.toggle("hidden", streak === 0);
  $("streak-days").textContent = streak;

  const counts = {};
  for (const v of Object.values(store.vocab)) counts[v.status] = (counts[v.status] || 0) + 1;
  const labels = [["new", "New"], ["learning", "Learning"], ["forgotten", "Forgotten"], ["unsure", "Unsure"], ["reviewing", "Reviewing"], ["mastered", "Mastered"]];
  $("vocab-status").innerHTML = labels
    .map(([key, label]) => `<span>${label} ${counts[key] || 0}</span>`)
    .join("");

  renderPracticeProgress();
}

/* ---------------------------------------------------------------------------
   クイズ設定（モード・問題数の選択）
--------------------------------------------------------------------------- */
let selectedMode = null;
let selectedCount = null;

function updateStartButton() {
  const notReady = !(selectedMode && selectedCount);
  $("btn-start-quiz").disabled = notReady;
  $("btn-start-quiz-only").disabled = notReady;
}

$("mode-grid").addEventListener("click", (e) => {
  const card = e.target.closest(".mode-card");
  if (!card) return;
  selectedMode = card.dataset.mode;
  document.querySelectorAll(".mode-card").forEach((c) => c.classList.toggle("selected", c === card));
  updateStartButton();
});

$("count-grid").addEventListener("click", (e) => {
  const card = e.target.closest(".count-card");
  if (!card) return;
  selectedCount = Number(card.dataset.count);
  document.querySelectorAll(".count-card").forEach((c) => c.classList.toggle("selected", c === card));
  updateStartButton();
});

/* ---------------------------------------------------------------------------
   出題選択（New：未出題優先 / Review：弱点語彙優先 / Random：混合）
--------------------------------------------------------------------------- */
function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function pickQuestions(mode, count) {
  const answered = store.answered;
  const isWeakTarget = (q) => {
    const v = store.vocab[norm(q.targetVocabulary)];
    return v && (v.status === "forgotten" || v.status === "unsure" || (v.wrongCount || 0) >= 1 || (v.nextReviewAt && v.nextReviewAt <= nowIso()));
  };
  const bank = activeQuestionBank();
  const unanswered = shuffle(bank.filter((q) => !answered[q.sentence]));
  const done = shuffle(bank.filter((q) => answered[q.sentence]))
    .sort((a, b) => (answered[a.sentence].last || "").localeCompare(answered[b.sentence].last || ""));

  let pool;
  if (mode === "new") {
    pool = [...unanswered, ...done];
  } else if (mode === "review") {
    const all = [...unanswered, ...done];
    pool = [...all.filter(isWeakTarget), ...all.filter((q) => !isWeakTarget(q))];
  } else {
    const all = [...unanswered, ...done];
    const weak = all.filter(isWeakTarget);
    const fresh = all.filter((q) => !isWeakTarget(q));
    const reviewCount = Math.min(weak.length, Math.floor(count * 0.4));
    const picked = weak.slice(0, reviewCount);
    const ids = new Set(picked.map((q) => q.sentence));
    pool = shuffle([...picked, ...fresh.filter((q) => !ids.has(q.sentence)).slice(0, count - reviewCount)]);
  }
  return pool.slice(0, count);
}

/* ---------------------------------------------------------------------------
   クイズ実行
--------------------------------------------------------------------------- */
const quiz = { questions: [], index: 0, correct: 0, wrong: [], answered: false };

/* ---------------------------------------------------------------------------
   タップ可能な文の描画（回答後）
   辞書にある語を最長一致（3語→2語→1語）でマークし、タップで意味を表示する
--------------------------------------------------------------------------- */
function interactiveHtml(text) {
  const tokens = text.split(/\s+/).filter(Boolean);
  const parts = [];
  let i = 0;
  while (i < tokens.length) {
    let matched = null;
    let matchLen = 0;
    // 句読点を除いた語幹で最長一致を探す
    for (let len = Math.min(3, tokens.length - i); len >= 1; len--) {
      const raw = tokens.slice(i, i + len).join(" ");
      const core = raw.replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu, "");
      if (core && lookupWord(core)) {
        matched = { raw, core };
        matchLen = len;
        break;
      }
    }
    if (matched) {
      const m = matched.raw.match(/^([^\p{L}\p{N}]*)(.*?)([^\p{L}\p{N}]*)$/u);
      parts.push(
        `${escapeHtml(m[1])}<span class="tap-word" data-word="${escapeHtml(matched.core)}">${escapeHtml(m[2])}</span>${escapeHtml(m[3])}`,
      );
      i += matchLen;
    } else {
      parts.push(escapeHtml(tokens[i]));
      i += 1;
    }
  }
  return parts.join(" ");
}

function renderSentenceInteractive(q) {
  const correctText = q.choices.find((c) => c.id === q.correctChoice).text;
  const segments = q.sentence.split(/_{2,}/);
  const filled = `<span class="tap-word filled" data-word="${escapeHtml(correctText)}">${escapeHtml(correctText)}</span>`;
  // interactiveHtmlは前後の空白を落とすため、空欄の前後に明示的にスペースを入れる
  $("quiz-sentence").innerHTML = segments.map(interactiveHtml).join(` ${filled} `);
  // 音声再生用に空欄を埋めた文を保持する
  quiz.filledSentence = q.sentence.replace(/_{2,}/, correctText);
}

function startQuiz(mode, count) {
  quiz.questions = pickQuestions(mode, count);
  quiz.index = 0;
  quiz.correct = 0;
  quiz.wrong = [];
  showScreen("quiz");
  renderQuestion();
}

$("btn-start-quiz").addEventListener("click", () => {
  startMixed(selectedMode, selectedCount);
});

$("btn-start-quiz-only").addEventListener("click", () => {
  startQuiz(selectedMode, selectedCount);
});

function renderQuestion() {
  window.scrollTo(0, 0);
  const q = quiz.questions[quiz.index];
  $("quiz-current").textContent = quiz.index + 1;
  $("quiz-total").textContent = quiz.questions.length;
  $("quiz-correct-count").textContent = quiz.correct;
  $("quiz-progress-fill").style.width = (quiz.index / quiz.questions.length) * 100 + "%";

  // 空欄を視覚的に強調（回答前に正解は表示しない）
  $("quiz-sentence").innerHTML = escapeHtml(q.sentence).replace(/_{2,}/g, '<span class="blank">？</span>');

  const choicesEl = $("quiz-choices");
  choicesEl.innerHTML = "";
  for (const choice of q.choices) {
    const btn = document.createElement("button");
    btn.className = "choice";
    btn.dataset.choice = choice.id;
    btn.innerHTML = `<span class="choice-id">${choice.id}</span><span>${escapeHtml(choice.text)}</span><span class="verdict"></span>`;
    // 回答前：回答として処理 / 回答後：単語の意味を表示
    btn.addEventListener("click", () => {
      if (quiz.answered) openWordPopup(choice.text);
      else answer(choice.id);
    });
    choicesEl.appendChild(btn);
  }
  quiz.answered = false;
  $("tap-hint").classList.add("hidden");
  $("quiz-audio-row").classList.add("hidden");
  $("quiz-feedback").classList.add("hidden");
}

function answer(choiceId) {
  const q = quiz.questions[quiz.index];
  const isCorrect = choiceId === q.correctChoice;
  if (isCorrect) quiz.correct++;
  else quiz.wrong.push({ q, selected: choiceId });

  // 記録：出題履歴・今日の統計・語彙
  const rec = store.answered[q.sentence] || { count: 0, correct: 0 };
  rec.count++;
  if (isCorrect) rec.correct++;
  rec.last = nowIso();
  store.answered[q.sentence] = rec;

  const day = store.days[todayStr()] || { questions: 0, correct: 0 };
  day.questions++;
  if (isCorrect) day.correct++;
  store.days[todayStr()] = day;

  upsertVocabFromQuestion(q, isCorrect);
  markPracticeDone("quiz", q.sentence);
  saveStore();

  quiz.answered = true;

  // 選択肢の正誤表示（ボタンは無効化せず、タップで単語の意味を表示できるようにする）
  document.querySelectorAll(".choice").forEach((btn) => {
    const id = btn.dataset.choice;
    if (id === q.correctChoice) {
      btn.classList.add("correct");
      btn.querySelector(".verdict").textContent = "正解";
    } else if (id === choiceId) {
      btn.classList.add("wrong");
      btn.querySelector(".verdict").textContent = "不正解";
    } else {
      btn.classList.add("dimmed");
    }
  });

  // 問題文をタップ可能にし、空欄を正解で埋める
  renderSentenceInteractive(q);
  $("tap-hint").classList.remove("hidden");
  $("quiz-audio-row").classList.remove("hidden");

  renderExplanation(q, isCorrect);
  $("quiz-correct-count").textContent = quiz.correct;
  $("quiz-feedback").classList.remove("hidden");
  $("btn-next").textContent = quiz.index + 1 < quiz.questions.length ? "次の問題へ" : "結果を見る";
}

/* --- 解説からFlash Cardへ追加 ---
   解説に出てくる語（重要語彙・選択肢の語・コロケーション）を、その場で
   「覚えていない語」としてFlash Cardの復習リストに入れられるようにする。
   すでに復習リストにある語はボタンを出さず「復習リスト」と表示する。 */

// その語が今日のフラッシュカードに出る状態か（buildDeckの条件と揃える）
function inReviewQueue(word) {
  const v = store.vocab[norm(word)];
  if (!v) return false;
  return v.status === "forgotten" || v.status === "unsure" || (v.nextReviewAt && v.nextReviewAt <= nowIso());
}

// 追加ボタンのHTML。意味・品詞は辞書に無い語のための予備データとして持たせる。
function addCardBtnHtml(word, meaningJP, partOfSpeech) {
  if (inReviewQueue(word)) return '<span class="add-card-btn is-added">✓ 復習リスト</span>';
  return `<button type="button" class="add-card-btn" data-add-word="${escapeHtml(word)}" data-add-meaning="${escapeHtml(meaningJP || "")}" data-add-pos="${escapeHtml(partOfSpeech || "")}">＋カード</button>`;
}

// 追加済みの見た目に差し替える（同じ語のボタンが複数箇所にあるためすべて更新する）
function markAddedButtons(word) {
  const key = norm(word);
  for (const btn of document.querySelectorAll(".add-card-btn[data-add-word]")) {
    if (norm(btn.dataset.addWord) === key) {
      btn.outerHTML = '<span class="add-card-btn is-added">✓ 追加しました</span>';
    }
  }
}

// 選択肢解説「語＝意味。…」から意味部分を取り出す（辞書構築と同じ形式）
function choiceMeaningFrom(explanationJP) {
  const m = explanationJP.match(/[＝=]\s*([^。]+)/);
  return m ? m[1].trim() : "";
}

function renderExplanation(q, isCorrect) {
  const correctText = q.choices.find((c) => c.id === q.correctChoice).text;
  const banner = $("feedback-banner");
  banner.className = "feedback-banner " + (isCorrect ? "ok" : "ng");
  banner.textContent = (isCorrect ? "正解です！ " : "不正解… ") + `正解は ${q.correctChoice}. ${correctText}`;

  $("exp-translation").textContent = q.translationJP;
  $("exp-main").textContent = q.explanationJP;

  $("exp-choices").innerHTML = q.choiceExplanations
    .map((e) => {
      const choiceText = (q.choices.find((c) => c.id === e.choice) || {}).text || "";
      // 解説の冒頭に出てくる選択肢の語をタップ可能にする
      const body = choiceText && e.explanationJP.startsWith(choiceText)
        ? `<span class="word tap-word" data-word="${escapeHtml(choiceText)}">${escapeHtml(choiceText)}</span>${escapeHtml(e.explanationJP.slice(choiceText.length))}`
        : escapeHtml(e.explanationJP);
      const meaning = choiceMeaningFrom(e.explanationJP);
      const add = choiceText && (meaning || lookupWord(choiceText))
        ? addCardBtnHtml(choiceText, meaning, "")
        : "";
      return `<li class="${e.choice === q.correctChoice ? "is-correct" : ""}"><span class="exp-choice-body"><strong>${e.choice}.</strong>${body}</span>${add}</li>`;
    })
    .join("");

  $("exp-vocab-wrap").classList.toggle("hidden", !q.vocabulary.length);
  $("exp-vocab").innerHTML = q.vocabulary
    .map((v) => `<li><span class="exp-vocab-body"><span class="word tap-word" data-word="${escapeHtml(v.word)}">${escapeHtml(v.word)}</span><span class="pos">〔${escapeHtml(v.partOfSpeech)}〕</span>${escapeHtml(v.meaningJP)}${v.explanationJP ? `<span class="muted"> — ${escapeHtml(v.explanationJP)}</span>` : ""}</span>${addCardBtnHtml(v.word, v.meaningJP, v.partOfSpeech)}</li>`)
    .join("");

  $("exp-grammar-wrap").classList.toggle("hidden", !q.grammar.length);
  $("exp-grammar").innerHTML = q.grammar
    .map((g) => `<li><p><span class="pattern">${escapeHtml(g.pattern)}</span> <span class="muted">${escapeHtml(g.meaningJP)}</span></p><p class="muted">${escapeHtml(g.explanationJP)}</p>${g.example ? `<p class="muted">例：${escapeHtml(g.example)}${g.exampleJP ? `（${escapeHtml(g.exampleJP)}）` : ""}</p>` : ""}</li>`)
    .join("");

  const colloc = q.collocations || [];
  $("exp-colloc-wrap").classList.toggle("hidden", !colloc.length);
  $("exp-colloc").innerHTML = colloc
    .map((c) => `<li><span class="tap-word" data-word="${escapeHtml(c.expression)}">${escapeHtml(c.expression)}</span>＝${escapeHtml(c.meaningJP)}${addCardBtnHtml(c.expression, c.meaningJP, "表現")}</li>`)
    .join("");

  $("exp-added-note").classList.add("hidden");
}

// 解説カード内：語のタップで意味を表示 / ＋カードでFlash Cardに追加
$("quiz-feedback").addEventListener("click", (e) => {
  const addBtn = e.target.closest(".add-card-btn[data-add-word]");
  if (addBtn) {
    const word = addBtn.dataset.addWord;
    const added = addWordToFlashcards(word, {
      meaningJP: addBtn.dataset.addMeaning,
      partOfSpeech: addBtn.dataset.addPos,
    });
    if (added) {
      markAddedButtons(word);
      $("exp-added-note").classList.remove("hidden");
    }
    return;
  }
  const span = e.target.closest(".tap-word");
  if (span) openWordPopup(span.dataset.word);
});

$("btn-next").addEventListener("click", () => {
  if (quiz.index + 1 < quiz.questions.length) {
    quiz.index++;
    renderQuestion();
  } else if (mixed.active) {
    mixedUnitDone("quiz");
  } else {
    saveSession();
    renderResult();
    showScreen("result");
  }
});

// 学習履歴の保存：1回のクイズ＝1セッション（間違えた語も記録する）
function saveSession() {
  store.sessions.push({
    at: nowIso(),
    mode: selectedMode,
    total: quiz.questions.length,
    correct: quiz.correct,
    wrong: quiz.wrong.map(({ q, selected }) => ({
      word: q.targetVocabulary,
      meaning:
        (q.vocabulary.find((v) => norm(v.word) === norm(q.targetVocabulary)) || {}).meaningJP || "",
      selected: (q.choices.find((c) => c.id === selected) || {}).text || "",
    })),
  });
  // 履歴は最新200件まで保持する
  if (store.sessions.length > 200) store.sessions = store.sessions.slice(-200);
  saveStore();
}

/* ---------------------------------------------------------------------------
   結果画面
--------------------------------------------------------------------------- */
function renderResult() {
  const total = quiz.questions.length;
  $("result-correct").textContent = quiz.correct;
  $("result-total").textContent = total;
  $("result-accuracy").textContent = `正答率 ${Math.round((quiz.correct / total) * 100)}%`;

  $("result-wrong-wrap").classList.toggle("hidden", quiz.wrong.length === 0);
  $("result-wrong-list").innerHTML = quiz.wrong
    .map(({ q, selected }) => {
      const selText = q.choices.find((c) => c.id === selected).text;
      return `<li><span class="word">${escapeHtml(q.targetVocabulary)}</span><span class="muted"> — あなたの回答：${escapeHtml(selText)}</span></li>`;
    })
    .join("");
}

// 結果画面から：今回間違えた語をそのままFlash Cardで復習する
// （全問正解だった場合は通常の復習デッキを開く）
$("btn-result-cards").addEventListener("click", () => {
  if (quiz.wrong.length > 0) {
    startFlashcardsFromWords(quiz.wrong.map(({ q }) => q.targetVocabulary));
  } else {
    startFlashcards();
  }
});

/* ---------------------------------------------------------------------------
   学習履歴画面
--------------------------------------------------------------------------- */
const MODE_LABEL = { new: "New", review: "Review", random: "Random", mixed: "ミックス", listening: "聴解", situation: "会話", passage: "読解", reading: "文章読解", builder: "並べ替え", sentListening: "文の聴解" };

function formatDateTime(iso) {
  const d = new Date(iso);
  return `${d.getFullYear()}/${d.getMonth() + 1}/${d.getDate()} ${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
}

function renderHistory() {
  const sessions = [...store.sessions].reverse();
  const wrongTotal = allWrongWords().length;

  $("all-wrong-count").textContent = wrongTotal;
  $("btn-review-all-wrong").disabled = wrongTotal === 0;
  $("history-actions").classList.toggle("hidden", sessions.length === 0 && wrongTotal === 0);
  $("history-empty").classList.toggle("hidden", sessions.length > 0);

  $("history-list").innerHTML = sessions
    .map((s, i) => {
      const percent = s.total > 0 ? Math.round((s.correct / s.total) * 100) : 0;
      const wrongChips = s.wrong
        .map(
          (w) =>
            `<span class="chip-wrong" title="あなたの回答：${escapeHtml(w.selected)}">${escapeHtml(w.word)}${w.meaning ? `（${escapeHtml(w.meaning)}）` : ""}</span>`,
        )
        .join("");
      const footer =
        s.wrong.length > 0
          ? `<div class="history-wrong">${wrongChips}</div>
             <button class="history-review-btn" data-session="${sessions.length - 1 - i}">この回の間違い${s.wrong.length}語をFlash Cardで復習</button>`
          : `<p class="history-perfect">全問正解でした 🎉</p>`;
      return `<li class="history-item">
        <div class="history-head">
          <span class="history-date">${formatDateTime(s.at)}</span>
          <span class="history-mode">${MODE_LABEL[s.mode] || s.mode}</span>
          <span class="history-score"><strong>${s.correct}</strong> / ${s.total}問（${percent}%）</span>
        </div>
        ${footer}
      </li>`;
    })
    .join("");
}

// セッションごとの「この回の間違いを復習」ボタン
$("history-list").addEventListener("click", (e) => {
  const btn = e.target.closest(".history-review-btn");
  if (!btn) return;
  const session = store.sessions[Number(btn.dataset.session)];
  if (session && session.wrong.length > 0) {
    startFlashcardsFromWords(session.wrong.map((w) => w.word));
  }
});

// 間違えたことのある語をすべて復習
$("btn-review-all-wrong").addEventListener("click", () => {
  const words = allWrongWords();
  if (words.length > 0) startFlashcardsFromWords(words);
});

/* ---------------------------------------------------------------------------
   フラッシュカード（今日の復習：forgotten → unsure → 期限到来の順）
--------------------------------------------------------------------------- */
const fc = { deck: [], index: 0, flipped: false, results: { forgotten: 0, unsure: 0, remembered: 0 } };

const BUCKET_LABEL = { forgotten: "覚えていない", unsure: "あやふや", due: "復習期限", new: "新規", wrong: "間違えた語" };

function buildDeck(limit = 10) {
  const now = nowIso();
  const order = { forgotten: 0, unsure: 1, due: 2, new: 3 };
  return Object.values(store.vocab)
    .map((v) => {
      let bucket = null;
      if (v.status === "forgotten") bucket = "forgotten";
      else if (v.status === "unsure") bucket = "unsure";
      else if (v.nextReviewAt && v.nextReviewAt <= now) bucket = "due";
      return bucket ? { v, bucket } : null;
    })
    .filter(Boolean)
    .sort((a, b) => order[a.bucket] - order[b.bucket] || (b.v.wrongCount || 0) - (a.v.wrongCount || 0))
    .slice(0, limit);
}

function openDeck(deck) {
  fc.deck = deck;
  fc.index = 0;
  fc.flipped = false;
  fc.results = { forgotten: 0, unsure: 0, remembered: 0 };
  showScreen("flashcards");
  $("fc-empty").classList.toggle("hidden", fc.deck.length > 0);
  $("fc-deck").classList.toggle("hidden", fc.deck.length === 0);
  if (fc.deck.length > 0) renderCard();
}

function startFlashcards() {
  openDeck(buildDeck(10));
}

// 指定した語のリストからデッキを作る（間違えた語の復習用）
function startFlashcardsFromWords(words) {
  const seen = new Set();
  const deck = [];
  for (const word of words) {
    const key = norm(word);
    if (seen.has(key)) continue;
    seen.add(key);
    const v = store.vocab[key];
    if (v) deck.push({ v, bucket: "wrong" });
  }
  openDeck(deck);
}

// 今までに1回でも間違えたことのある語すべて（間違い回数の多い順）
function allWrongWords() {
  return Object.values(store.vocab)
    .filter((v) => (v.wrongCount || 0) >= 1)
    .sort((a, b) => (b.wrongCount || 0) - (a.wrongCount || 0))
    .map((v) => v.word);
}

$("btn-start-cards").addEventListener("click", startFlashcards);

function renderCard() {
  window.scrollTo(0, 0);
  const { v, bucket } = fc.deck[fc.index];
  $("card-current").textContent = fc.index + 1;
  $("card-total").textContent = fc.deck.length;
  $("card-bucket").textContent = BUCKET_LABEL[bucket];

  fc.flipped = false;
  $("fc-front").classList.remove("hidden");
  $("fc-back").classList.add("hidden");
  $("fc-controls").classList.add("hidden");
  $("fc-tap-hint").classList.remove("hidden");

  $("fc-word").textContent = v.word;
  $("fc-pos").textContent = v.partOfSpeech ? `〔${v.partOfSpeech}〕` : "";
  $("fc-back-word").textContent = v.word;
  $("fc-back-pos").textContent = v.partOfSpeech ? `〔${v.partOfSpeech}〕` : "";
  $("fc-meaning").textContent = v.meaningJP || "（意味未登録）";

  const hasExample = Boolean(v.example);
  $("fc-example").classList.toggle("hidden", !hasExample);
  $("fc-example-vi").textContent = v.example || "";
  $("fc-example-ja").textContent = v.exampleJP || "";

  $("fc-colloc").innerHTML = (v.collocations || [])
    .map((c) => `<li>${escapeHtml(c.expression)}＝${escapeHtml(c.meaningJP)}</li>`)
    .join("");
}

function flipCard() {
  fc.flipped = !fc.flipped;
  $("fc-front").classList.toggle("hidden", fc.flipped);
  $("fc-back").classList.toggle("hidden", !fc.flipped);
  $("fc-controls").classList.toggle("hidden", !fc.flipped);
  $("fc-tap-hint").classList.toggle("hidden", fc.flipped);
}

$("flashcard").addEventListener("click", (e) => {
  // 発音ボタンはめくり動作にしない
  const speakBtn = e.target.closest(".speak-btn");
  if (speakBtn) {
    const card = fc.deck[fc.index];
    if (!card) return;
    if (speakBtn.hasAttribute("data-speak-example")) {
      speak(card.v.example || card.v.word, speakBtn);
    } else {
      speak(card.v.word, speakBtn);
    }
    return;
  }
  flipCard();
});

// キーボード操作（Enter / Space）でもめくれるようにする
$("flashcard").addEventListener("keydown", (e) => {
  if (e.key === "Enter" || e.key === " ") {
    e.preventDefault();
    flipCard();
  }
});

$("fc-controls").addEventListener("click", (e) => {
  const btn = e.target.closest("[data-rate]");
  if (!btn) return;
  const rate = btn.dataset.rate;
  const { v } = fc.deck[fc.index];
  applyVocabEvent(v, rate);
  saveStore();
  fc.results[rate]++;

  if (fc.index + 1 < fc.deck.length) {
    fc.index++;
    renderCard();
  } else {
    $("fc-done-count").textContent = fc.deck.length;
    $("sum-forgotten").textContent = fc.results.forgotten;
    $("sum-unsure").textContent = fc.results.unsure;
    $("sum-remembered").textContent = fc.results.remembered;
    showScreen("fc-done");
  }
});

