for (const r of B2_READING_BANK) for (const q of r.questions) addDictEntry(q.key[0], q.key[1], q.key[2]);

const reading = { r: null, qIndex: 0, correct: 0, wrong: [], answered: false };

function readingTextHtml(r, interactive) {
  const lines = r.text.split("\n");
  const bodyHtml = lines
    .map((line) => (interactive ? interactiveHtml(line) : escapeHtml(line)))
    .join("<br>");
  if (r.kind === "notice") {
    return `<div class="notice-box"><p class="notice-title">THÔNG BÁO</p><p>${bodyHtml}</p></div>`;
  }
  return `<div class="card passage-card"><p>${bodyHtml}</p></div>`;
}

function startReading() {
  const bank = pickBankByLevel({ A2: READING_BANK, B1: B1_READING_BANK, B2: B2_READING_BANK });
  reading.r = shuffle(bank)[0];
  reading.qIndex = 0;
  reading.correct = 0;
  reading.wrong = [];
  reading.answered = false;
  showScreen("reading");
  $("rd-question").classList.remove("hidden");
  $("rdg-result").classList.add("hidden");
  $("rdg-lead").textContent =
    reading.r.kind === "notice"
      ? "お知らせを読んで、質問に答えてください"
      : "文章を読んで、質問に答えてください";
  $("rdg-text-wrap").innerHTML = readingTextHtml(reading.r, false);
  renderReadingQuestion();
}

/* ---------------------------------------------------------------------------
   フィードバック（回答後）の共通表示
   解説文の中のベトナム語をタップ可能にし、重要語彙をFlash Cardへ追加できるようにする。
   クイズの解説（renderExplanation）と同じ操作感を、他の練習タイプでも使えるようにまとめる。
--------------------------------------------------------------------------- */

// 解説文（日本語）のうち「」で囲まれたベトナム語だけを辞書タップ可能にする。
// 日本語部分に interactiveHtml をかけると誤検出するため、引用部分だけを通す。
function explanationHtml(text) {
  const raw = String(text || "");
  let out = "";
  let i = 0;
  while (i < raw.length) {
    const open = raw.indexOf("「", i);
    if (open === -1) {
      out += escapeHtml(raw.slice(i));
      break;
    }
    const close = raw.indexOf("」", open + 1);
    if (close === -1) {
      out += escapeHtml(raw.slice(i));
      break;
    }
    out += escapeHtml(raw.slice(i, open + 1));
    out += interactiveHtml(raw.slice(open + 1, close));
    out += escapeHtml("」");
    i = close + 1;
  }
  return out;
}

// キーフレーズ（[語, 意味, 品詞]）の1行。語はタップで辞書、＋カードでFlash Cardへ。
function keyPhraseHtml(key) {
  if (!key || !key[0]) return "";
  const [word, meaning, pos] = key;
  return `<span class="exp-vocab-body"><span class="word tap-word" data-word="${escapeHtml(word)}">${escapeHtml(word)}</span>${pos ? `<span class="pos">〔${escapeHtml(pos)}〕</span>` : ""}${escapeHtml(meaning || "")}</span>${addCardBtnHtml(word, meaning || "", pos || "")}`;
}

// フィードバック領域のクリックを1か所で受ける（語タップ＝意味、＋カード＝Flash Card追加）
function bindFeedbackInteractions(elementId, addedNoteId) {
  const el = $(elementId);
  if (!el) return;
  el.addEventListener("click", (e) => {
    const addBtn = e.target.closest(".add-card-btn[data-add-word]");
    if (addBtn) {
      const added = addWordToFlashcards(addBtn.dataset.addWord, {
        meaningJP: addBtn.dataset.addMeaning,
        partOfSpeech: addBtn.dataset.addPos,
      });
      if (added) {
        markAddedButtons(addBtn.dataset.addWord);
        if (addedNoteId && $(addedNoteId)) $(addedNoteId).classList.remove("hidden");
      }
      return;
    }
    const span = e.target.closest(".tap-word");
    if (span) openWordPopup(span.dataset.word);
  });
}

function renderReadingQuestion() {
  window.scrollTo(0, 0);
  const r = reading.r;
  const question = r.questions[reading.qIndex];
  reading.answered = false;

  $("rdg-current").textContent = reading.qIndex + 1;
  $("rdg-total").textContent = r.questions.length;
  $("rdg-correct-count").textContent = reading.correct;
  $("rdg-progress-fill").style.width = (reading.qIndex / r.questions.length) * 100 + "%";
  $("rdg-tap-hint").classList.add("hidden");
  $("rdg-q").textContent = `質問${reading.qIndex + 1}：${question.q}`;

  const letters = ["A", "B", "C", "D"];
  $("rdg-choices").innerHTML = "";
  question.c.forEach((text, i) => {
    const btn = document.createElement("button");
    btn.className = "choice";
    btn.dataset.index = i;
    btn.innerHTML = `<span class="choice-id">${letters[i]}</span><span>${escapeHtml(text)}</span><span class="verdict"></span>`;
    btn.addEventListener("click", () => {
      if (!reading.answered) answerReading(i);
    });
    $("rdg-choices").appendChild(btn);
  });
  $("rdg-feedback").classList.add("hidden");
}

function answerReading(selectedIndex) {
  const r = reading.r;
  const question = r.questions[reading.qIndex];
  const isCorrect = selectedIndex === question.a;
  reading.answered = true;
  if (isCorrect) reading.correct++;
  else reading.wrong.push({ word: question.key[0], meaning: question.key[1], selected: question.c[selectedIndex] });

  const day = store.days[todayStr()] || { questions: 0, correct: 0 };
  day.questions++;
  if (isCorrect) day.correct++;
  store.days[todayStr()] = day;
  if (!isCorrect) addWordToFlashcards(question.key[0]);
  markPracticeDone("reading", r.text + "#" + reading.qIndex);
  saveStore();

  document.querySelectorAll("#rdg-choices .choice").forEach((btn) => {
    const i = Number(btn.dataset.index);
    if (i === question.a) {
      btn.classList.add("correct");
      btn.querySelector(".verdict").textContent = "正解";
    } else if (i === selectedIndex) {
      btn.classList.add("wrong");
      btn.querySelector(".verdict").textContent = "不正解";
    } else {
      btn.classList.add("dimmed");
    }
  });

  const letters = ["A", "B", "C", "D"];
  const banner = $("rdg-banner");
  banner.className = "feedback-banner " + (isCorrect ? "ok" : "ng");
  banner.textContent =
    (isCorrect ? "正解です！ " : "不正解… ") + `正解は ${letters[question.a]}. ${question.c[question.a]}`;
  $("rdg-explanation").innerHTML = explanationHtml(question.e);
  // 重要語彙（データのキーフレーズ）と、読み違いを確かめるための日本語訳
  $("rdg-key-wrap").classList.toggle("hidden", !question.key || !question.key[0]);
  $("rdg-key").innerHTML = keyPhraseHtml(question.key);
  $("rdg-jp").textContent = r.t || "";
  $("rdg-added-note").classList.add("hidden");
  // 回答後は本文の語もタップして意味を確認できるようにする
  $("rdg-text-wrap").innerHTML = readingTextHtml(r, true);
  $("rdg-tap-hint").classList.remove("hidden");
  $("rdg-next").textContent =
    reading.qIndex + 1 < r.questions.length ? "次の問題へ" : "結果を見る";
  $("rdg-feedback").classList.remove("hidden");
  $("rdg-correct-count").textContent = reading.correct;
}

function finishReading() {
  const r = reading.r;
  store.sessions.push({
    at: nowIso(),
    mode: "reading",
    total: r.questions.length,
    correct: reading.correct,
    wrong: reading.wrong,
  });
  if (store.sessions.length > 200) store.sessions = store.sessions.slice(-200);
  saveStore();

  $("rd-question").classList.add("hidden");
  $("rdg-result").classList.remove("hidden");
  $("rdg-result-correct").textContent = reading.correct;
  $("rdg-result-total").textContent = r.questions.length;
  $("rdg-result-note").textContent = `正答率 ${Math.round((reading.correct / r.questions.length) * 100)}%`;
  $("rdg-text-final-wrap").innerHTML = readingTextHtml(r, true);
  $("rdg-translation").textContent = r.t;
  $("rdg-wrong-wrap").classList.toggle("hidden", reading.wrong.length === 0);
  $("rdg-wrong-list").innerHTML = reading.wrong
    .map(
      (w) =>
        `<li><span class="exp-vocab-body"><span class="word tap-word" data-word="${escapeHtml(w.word)}">${escapeHtml(w.word)}</span><span class="muted">（${escapeHtml(w.meaning)}）— あなたの回答：${escapeHtml(w.selected)}</span></span>${addCardBtnHtml(w.word, w.meaning, "")}</li>`,
    )
    .join("");
  window.scrollTo(0, 0);
}

$("btn-start-reading").addEventListener("click", startReading);
// 回答後の解説内：語タップで意味、＋カードでFlash Cardへ（クイズの解説と同じ操作）
bindFeedbackInteractions("rdg-feedback", "rdg-added-note");
bindFeedbackInteractions("pg-feedback", "pg-added-note");
bindFeedbackInteractions("st-feedback", "st-added-note");
bindFeedbackInteractions("bd-feedback", "bd-added-note");
bindFeedbackInteractions("sl-feedback", "sl-added-note");

$("rdg-next").addEventListener("click", () => {
  if (reading.qIndex + 1 < reading.r.questions.length) {
    reading.qIndex++;
    renderReadingQuestion();
  } else if (mixed.active) {
    mixedUnitDone("reading");
  } else {
    finishReading();
  }
});
$("rdg-again").addEventListener("click", startReading);
