/* ---------------------------------------------------------------------------
   学習データのバックアップ（エクスポート／インポート／リセット）
   データはこの端末のlocalStorageにしか無いため、持ち出しと復元の手段を用意する。
--------------------------------------------------------------------------- */
let pendingImport = null; // 読み込み済みバックアップ（上書き／マージの選択待ち）

function showSettingsMessage(message, kind) {
  const el = $("settings-message");
  el.textContent = message;
  el.className = "settings-message " + kind; // ok / ng
}

// store は const なので、中身を入れ替える形で反映する
function applyStore(next) {
  for (const key of Object.keys(store)) delete store[key];
  Object.assign(store, next);
  renderLevelControl();
  renderSpeedControls();
  renderHome();
}

/* --- エクスポート --- */
function exportStore() {
  const blob = new Blob([JSON.stringify(store, null, 2)], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const fileName = `kazu-backup-${todayStr()}.json`;
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 0); // クリック直後に解放するとDLが中断される環境がある
  showSettingsMessage(`バックアップ「${fileName}」を保存しました。`, "ok");
}

/* --- インポート --- */
// KAZUのバックアップとして読めるかを確認する。読めない場合はnullを返し、既存データには触らない。
function parseBackup(text) {
  let data = null;
  try {
    data = JSON.parse(text);
  } catch (_) {
    return null;
  }
  if (!isPlainObject(data)) return null;
  const looksLikeStore =
    isPlainObject(data.vocab) ||
    isPlainObject(data.answered) ||
    isPlainObject(data.days) ||
    Array.isArray(data.sessions);
  if (!looksLikeStore) return null;
  return migrate(data); // 版の違うバックアップもここで今の版に合わせる
}

// 語彙：学習回数は合算し、進み具合は「進んでいるほう」を採る
function mergeVocabRecord(cur, inc) {
  const curSeen = cur.lastReviewedAt || cur.firstSeenAt || "";
  const incSeen = inc.lastReviewedAt || inc.firstSeenAt || "";
  const newer = incSeen >= curSeen ? inc : cur;
  return {
    ...cur,
    ...inc,
    exposureCount: cur.exposureCount + inc.exposureCount,
    wrongCount: cur.wrongCount + inc.wrongCount,
    consecutiveCorrect: Math.max(cur.consecutiveCorrect, inc.consecutiveCorrect),
    consecutiveWrong: Math.max(cur.consecutiveWrong, inc.consecutiveWrong),
    masteryScore: Math.max(cur.masteryScore, inc.masteryScore),
    status: newer.status,
    firstSeenAt: cur.firstSeenAt < inc.firstSeenAt ? cur.firstSeenAt : inc.firstSeenAt,
    // 復習期限は早いほうを採る（復習漏れを作らない）
    nextReviewAt: cur.nextReviewAt < inc.nextReviewAt ? cur.nextReviewAt : inc.nextReviewAt,
  };
}

// マージ：語彙・回答・日別記録は数を合算し、セッションは日時(at)で重複排除する
function mergeStores(base, incoming) {
  const merged = { ...base, version: SCHEMA_VERSION };

  merged.vocab = { ...base.vocab };
  for (const [key, inc] of Object.entries(incoming.vocab)) {
    const cur = merged.vocab[key];
    merged.vocab[key] = cur ? mergeVocabRecord(cur, inc) : inc;
  }

  merged.answered = { ...base.answered };
  for (const [sentence, inc] of Object.entries(incoming.answered)) {
    const cur = merged.answered[sentence];
    merged.answered[sentence] = cur
      ? { ...cur, count: cur.count + inc.count, correct: cur.correct + inc.correct }
      : inc;
  }

  merged.days = { ...base.days };
  for (const [day, inc] of Object.entries(incoming.days)) {
    const cur = merged.days[day];
    merged.days[day] = cur
      ? { ...cur, questions: cur.questions + inc.questions, correct: cur.correct + inc.correct }
      : inc;
  }

  const byAt = new Map();
  for (const s of [...base.sessions, ...incoming.sessions]) byAt.set(s.at, s);
  merged.sessions = [...byAt.values()].sort((a, b) => (a.at < b.at ? -1 : a.at > b.at ? 1 : 0)).slice(-200);

  // 練習の進捗は「どちらかで解いていれば解いた」とみなして両方を足し合わせる
  merged.progress = {};
  for (const type of PRACTICE_TYPES) {
    const union = { ...((base.progress || {})[type] || {}), ...((incoming.progress || {})[type] || {}) };
    if (Object.keys(union).length > 0) merged.progress[type] = union;
  }

  return merged;
}

function openImportDialog(backup) {
  $("import-summary").textContent =
    `語彙 ${Object.keys(backup.vocab).length}語 / 学習履歴 ${backup.sessions.length}回 / ` +
    `学習日 ${Object.keys(backup.days).length}日 のバックアップです。`;
  $("import-overlay").classList.remove("hidden");
}

function closeImportDialog() {
  $("import-overlay").classList.add("hidden");
  pendingImport = null;
}

function applyImport(mode) {
  if (!pendingImport) return;
  const next = mode === "merge" ? mergeStores(store, pendingImport) : pendingImport;
  closeImportDialog();
  applyStore(next);
  saveStore();
  showSettingsMessage(
    `バックアップを${mode === "merge" ? "今のデータと合わせて" : "上書きで"}読み込みました。` +
      `語彙 ${Object.keys(store.vocab).length}語 / 学習履歴 ${store.sessions.length}回。`,
    "ok",
  );
}

/* --- リセット --- */
function resetStore() {
  const ok = window.confirm(
    "この端末の学習データがすべて消えます。よろしいですか？\nバックアップを保存していない場合、元に戻せません。",
  );
  if (!ok) return;
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch (_) { /* 消せなくても画面上のデータは初期化する */ }
  applyStore(emptyStore());
  showSettingsMessage("学習データを削除しました。", "ok");
}

/* --- 操作 --- */
$("btn-export").addEventListener("click", exportStore);
$("btn-reset").addEventListener("click", resetStore);
$("btn-import").addEventListener("click", () => $("import-file").click());

$("import-file").addEventListener("change", (e) => {
  const file = e.target.files[0];
  e.target.value = ""; // 同じファイルを続けて選び直せるようにする
  if (!file) return;
  const reader = new FileReader();
  reader.onload = () => {
    const backup = parseBackup(String(reader.result));
    if (!backup) {
      showSettingsMessage(
        "このファイルはKAZUのバックアップとして読み込めませんでした。学習データはそのままです。",
        "ng",
      );
      return;
    }
    pendingImport = backup;
    openImportDialog(backup);
  };
  reader.onerror = () => {
    showSettingsMessage("ファイルを読み込めませんでした。学習データはそのままです。", "ng");
  };
  reader.readAsText(file);
});

$("import-merge").addEventListener("click", () => applyImport("merge"));
$("import-replace").addEventListener("click", () => applyImport("replace"));
$("import-cancel").addEventListener("click", closeImportDialog);
$("import-overlay").addEventListener("click", (e) => {
  if (e.target === $("import-overlay")) closeImportDialog();
});

/* ---------------------------------------------------------------------------
   ミックス練習：レベル→モード→問題数を選ぶと、全練習タイプから
   ランダムに混ぜて出題する。各タイプの既存画面をそのまま使い、
   1ユニット（1問。読解系は1文章＝複数問）終わるごとに次のタイプへ切り替える。
--------------------------------------------------------------------------- */
const MIXED_TYPE_LABELS = {
  quiz: "📝 語彙クイズ",
  listening: "🎧 聴解",
  situation: "💬 会話",
  passage: "📖 読解空欄",
  reading: "📰 文章読解",
  builder: "🧩 並べ替え",
  sentlisten: "🔉 文の聴解",
};

const mixed = {
  active: false,
  units: [],
  step: 0,
  slotsDone: 0,
  totalSlots: 0,
  correct: 0,
  wrong: [],
  perType: {},
};

// 出題プランを組み立てる。1スロット＝1問。読解系は文章単位でまとめて消費する。
// クイズはモード（new/review/random）の選択ロジックをそのまま使う。
function buildMixedUnits(mode, count) {
  const units = [];
  let remaining = count;

  const quizPool = pickQuestions(mode, count);
  let quizUsed = 0;
  const situationPool = shuffle(pickBankByLevel({ A2: SITUATION_BANK, B1: B1_SITUATION_BANK, B2: B2_SITUATION_BANK }));
  const builderPool = shuffle(pickBankByLevel({ A2: BUILDER_BANK, B1: B1_BUILDER_BANK, B2: B2_BUILDER_BANK }));
  const passagePool = shuffle(pickBankByLevel({ A2: PASSAGE_BANK, B1: B1_PASSAGE_BANK, B2: B2_PASSAGE_BANK }));
  const readingPool = shuffle(pickBankByLevel({ A2: READING_BANK, B1: B1_READING_BANK, B2: B2_READING_BANK }));
  const listeningPool = shuffle(listeningAnswerPool());
  const sentBank = sentListenBank();
  const sentPool = shuffle(sentBank);

  // 読解系は時間がかかるため、1セッションに文章1本ずつまで
  let usedPassage = false;
  let usedReading = false;

  while (remaining > 0) {
    // クイズ（語彙の中心）は他タイプより出やすくする（重み2）
    const options = [];
    if (quizUsed < quizPool.length) options.push("quiz", "quiz");
    if (situationPool.length) options.push("situation");
    if (builderPool.length) options.push("builder");
    if (listeningPool.length) options.push("listening");
    if (sentPool.length) options.push("sentlisten");
    if (!usedPassage && passagePool.some((p) => p.blanks.length <= remaining)) options.push("passage");
    if (!usedReading && readingPool.some((r) => r.questions.length <= remaining)) options.push("reading");
    if (options.length === 0) break;

    const type = options[Math.floor(Math.random() * options.length)];
    if (type === "quiz") {
      units.push({ type, q: quizPool[quizUsed++], slots: 1 });
      remaining -= 1;
    } else if (type === "situation") {
      units.push({ type, q: situationPool.shift(), slots: 1 });
      remaining -= 1;
    } else if (type === "builder") {
      units.push({ type, q: builderPool.shift(), slots: 1 });
      remaining -= 1;
    } else if (type === "listening") {
      const entry = listeningPool.shift();
      units.push({ type, q: { entry, choices: shuffle([entry.word, ...getSoundAlikes(entry.word, 3)]) }, slots: 1 });
      remaining -= 1;
    } else if (type === "sentlisten") {
      const item = sentPool.shift();
      const others = sentBank.filter((o) => o.translationJP !== item.translationJP);
      const sameCat = shuffle(others.filter((o) => o.category === item.category));
      const rest = shuffle(others.filter((o) => o.category !== item.category));
      const distractors = [...sameCat, ...rest].slice(0, 3).map((o) => o.translationJP);
      units.push({ type, q: { ...item, choices: shuffle([item.translationJP, ...distractors]) }, slots: 1 });
      remaining -= 1;
    } else if (type === "passage") {
      const idx = passagePool.findIndex((p) => p.blanks.length <= remaining);
      const p = passagePool.splice(idx, 1)[0];
      units.push({ type, q: p, slots: p.blanks.length });
      remaining -= p.blanks.length;
      usedPassage = true;
    } else if (type === "reading") {
      const idx = readingPool.findIndex((r) => r.questions.length <= remaining);
      const r = readingPool.splice(idx, 1)[0];
      units.push({ type, q: r, slots: r.questions.length });
      remaining -= r.questions.length;
      usedReading = true;
    }
  }
  return shuffle(units);
}

function startMixed(mode, count) {
  const units = buildMixedUnits(mode, count);
  if (units.length === 0) return;
  mixed.active = true;
  mixed.units = units;
  mixed.step = 0;
  mixed.slotsDone = 0;
  mixed.totalSlots = units.reduce((sum, u) => sum + u.slots, 0);
  mixed.correct = 0;
  mixed.wrong = [];
  mixed.perType = {};
  mixedShowUnit();
}

// 単問タイプの進捗表示を「ミックス全体の進捗」に差し替える
// （読解系は文章内の空欄・設問の進捗のほうが分かりやすいのでそのまま）
function mixedPatchProgress(prefix) {
  $(prefix + "-current").textContent = mixed.slotsDone + 1;
  $(prefix + "-total").textContent = mixed.totalSlots;
  $(prefix + "-progress-fill").style.width = (mixed.slotsDone / mixed.totalSlots) * 100 + "%";
}

function mixedShowUnit() {
  const unit = mixed.units[mixed.step];
  if (unit.type === "quiz") {
    quiz.questions = [unit.q];
    quiz.index = 0;
    quiz.correct = 0;
    quiz.wrong = [];
    showScreen("quiz");
    renderQuestion();
    mixedPatchProgress("quiz");
  } else if (unit.type === "situation") {
    situation.questions = [unit.q];
    situation.index = 0;
    situation.correct = 0;
    situation.wrong = [];
    situation.answered = false;
    showScreen("situation");
    $("st-question").classList.remove("hidden");
    $("st-result").classList.add("hidden");
    renderSituationQuestion();
    mixedPatchProgress("st");
  } else if (unit.type === "builder") {
    builder.questions = [unit.q];
    builder.index = 0;
    builder.correct = 0;
    builder.wrong = [];
    showScreen("builder");
    $("bd-question").classList.remove("hidden");
    $("bd-result").classList.add("hidden");
    renderBuilderQuestion();
    mixedPatchProgress("bd");
  } else if (unit.type === "listening") {
    listening.questions = [unit.q];
    listening.index = 0;
    listening.correct = 0;
    listening.wrong = [];
    showScreen("listening");
    $("ls-question").classList.remove("hidden");
    $("ls-result").classList.add("hidden");
    renderListeningQuestion();
    mixedPatchProgress("ls");
  } else if (unit.type === "sentlisten") {
    sentListen.questions = [unit.q];
    sentListen.index = 0;
    sentListen.correct = 0;
    sentListen.wrong = [];
    showScreen("sentlisten");
    $("sl-question").classList.remove("hidden");
    $("sl-result").classList.add("hidden");
    renderSentListenQuestion();
    mixedPatchProgress("sl");
  } else if (unit.type === "passage") {
    passage.p = unit.q;
    passage.blankIndex = 0;
    passage.correct = 0;
    passage.wrong = [];
    passage.results = [];
    passage.answered = false;
    showScreen("passage");
    $("pg-question").classList.remove("hidden");
    $("pg-result").classList.add("hidden");
    renderPassageBlank();
  } else if (unit.type === "reading") {
    reading.r = unit.q;
    reading.qIndex = 0;
    reading.correct = 0;
    reading.wrong = [];
    reading.answered = false;
    showScreen("reading");
    $("rd-question").classList.remove("hidden");
    $("rdg-result").classList.add("hidden");
    $("rdg-lead").textContent =
      reading.r.kind === "notice"
        ? "お知らせを読んで、質問に答えてください"
        : "文章を読んで、質問に答えてください";
    $("rdg-text-wrap").innerHTML = readingTextHtml(reading.r, false);
    renderReadingQuestion();
  }
}

// 1ユニット終了：そのタイプのstateから成績を回収し、次のユニットへ
function mixedUnitDone(type) {
  const unit = mixed.units[mixed.step];
  let correct = 0;
  let wrong = [];
  if (type === "quiz") {
    correct = quiz.correct;
    wrong = quiz.wrong.map(({ q, selected }) => ({
      word: q.targetVocabulary,
      meaning:
        (q.vocabulary.find((v) => norm(v.word) === norm(q.targetVocabulary)) || {}).meaningJP || "",
      selected: (q.choices.find((c) => c.id === selected) || {}).text || "",
    }));
  } else if (type === "situation") {
    correct = situation.correct;
    wrong = situation.wrong;
  } else if (type === "builder") {
    correct = builder.correct;
    wrong = builder.wrong;
  } else if (type === "listening") {
    correct = listening.correct;
    wrong = listening.wrong;
  } else if (type === "sentlisten") {
    correct = sentListen.correct;
    wrong = sentListen.wrong;
  } else if (type === "passage") {
    correct = passage.correct;
    wrong = passage.wrong;
  } else if (type === "reading") {
    correct = reading.correct;
    wrong = reading.wrong;
  }

  mixed.correct += correct;
  mixed.wrong.push(...wrong);
  const pt = mixed.perType[type] || { correct: 0, total: 0 };
  pt.correct += correct;
  pt.total += unit.slots;
  mixed.perType[type] = pt;
  mixed.slotsDone += unit.slots;

  mixed.step++;
  if (mixed.step < mixed.units.length) mixedShowUnit();
  else finishMixed();
}

function finishMixed() {
  mixed.active = false;
  store.sessions.push({
    at: nowIso(),
    mode: "mixed",
    total: mixed.totalSlots,
    correct: mixed.correct,
    wrong: mixed.wrong,
  });
  if (store.sessions.length > 200) store.sessions = store.sessions.slice(-200);
  saveStore();
  renderMixedResult();
  showScreen("mixedresult");
}

// ミックスで読んだ文章（文章読解・読解空欄）を、単体の結果画面と同じ情報量で残す
function renderMixedTexts() {
  const units = mixed.units
    .slice(0, mixed.step)
    .filter((u) => u.type === "reading" || u.type === "passage");

  $("mx-texts-wrap").classList.toggle("hidden", units.length === 0);
  $("mx-added-note").classList.add("hidden");
  if (units.length === 0) {
    $("mx-texts").innerHTML = "";
    return;
  }

  $("mx-texts").innerHTML = units
    .map((unit) => {
      const q = unit.q;
      const label = unit.type === "reading" ? "文章読解" : "読解練習（空欄補充）";
      const textHtml =
        unit.type === "reading" ? readingTextHtml(q, true) : `<div class="card passage-card"><p>${passageTextHtml(q)}</p></div>`;
      // 設問（reading）／空欄（passage）ごとの解説と重要語彙
      const items = unit.type === "reading" ? q.questions : q.blanks;
      const itemsHtml = items
        .map((item, i) => {
          const heading =
            unit.type === "reading" ? `質問${i + 1}：${escapeHtml(item.q)}` : `空欄${i + 1}：${escapeHtml(item.c[item.a])}`;
          return `<li>
            <p class="mx-exp-head">${heading}</p>
            <p>${explanationHtml(item.e)}</p>
            ${item.key && item.key[0] ? `<p class="exp-vocab-row">${keyPhraseHtml(item.key)}</p>` : ""}
          </li>`;
        })
        .join("");

      return `<div class="card explanation mx-text-card">
        <h3>${label}</h3>
        ${textHtml}
        <details class="jp-details"><summary>日本語訳を見る</summary><p>${escapeHtml(q.t || "")}</p></details>
        <h3>設問の解説</h3>
        <ul class="mx-exp-list">${itemsHtml}</ul>
      </div>`;
    })
    .join("");
}

function renderMixedResult() {
  $("mx-correct").textContent = mixed.correct;
  $("mx-total").textContent = mixed.totalSlots;
  $("mx-accuracy").textContent = `正答率 ${Math.round((mixed.correct / mixed.totalSlots) * 100)}%`;

  $("mx-type-list").innerHTML = Object.keys(MIXED_TYPE_LABELS)
    .filter((type) => mixed.perType[type])
    .map((type) => {
      const s = mixed.perType[type];
      return `<li><span>${MIXED_TYPE_LABELS[type]}</span><span class="muted">　${s.correct} / ${s.total}問</span></li>`;
    })
    .join("");

  // その回に出た読解ユニットの本文・日本語訳・設問の解説を残す。
  // ミックスでは各タイプの結果画面を通らないため、ここに出さないと読み返せない。
  renderMixedTexts();

  $("mx-wrong-wrap").classList.toggle("hidden", mixed.wrong.length === 0);
  $("mx-wrong-list").innerHTML = mixed.wrong
    .map(
      (w) =>
        `<li><span class="exp-vocab-body"><span class="word tap-word" data-word="${escapeHtml(w.word)}">${escapeHtml(w.word)}</span><span class="muted">（${escapeHtml(w.meaning)}）</span></span>${addCardBtnHtml(w.word, w.meaning, "")}</li>`,
    )
    .join("");
}

// 読んだ文章の中：語タップで意味、＋カードでFlash Cardへ
bindFeedbackInteractions("mx-texts", "mx-added-note");

$("mx-again").addEventListener("click", () => startMixed(selectedMode || "random", selectedCount || 10));

// 間違えた語のタップ＝意味ポップアップ、「＋カード」＝Flash Cardへ追加
// （辞書に無い語も、ミックス結果が持つ意味を予備データとして使えるようにする）
$("mx-wrong-list").addEventListener("click", (e) => {
  const addBtn = e.target.closest(".add-card-btn[data-add-word]");
  if (addBtn) {
    const added = addWordToFlashcards(addBtn.dataset.addWord, {
      meaningJP: addBtn.dataset.addMeaning,
      partOfSpeech: addBtn.dataset.addPos,
    });
    if (added) markAddedButtons(addBtn.dataset.addWord);
    return;
  }
  const span = e.target.closest(".tap-word");
  if (span) openWordPopup(span.dataset.word);
});

// 今回間違えた語をそのままFlash Cardで復習する。
// 辞書に無い語も意味の予備データ付きで登録してからデッキを開く。
// （全問正解だった場合は通常の復習デッキを開く）
$("mx-cards").addEventListener("click", () => {
  if (mixed.wrong.length > 0) {
    for (const w of mixed.wrong) {
      addWordToFlashcards(w.word, { meaningJP: w.meaning });
    }
    startFlashcardsFromWords(mixed.wrong.map((w) => w.word));
  } else {
    startFlashcards();
  }
});

/* ---------------------------------------------------------------------------
   ナビゲーション
--------------------------------------------------------------------------- */
document.querySelectorAll("[data-nav]").forEach((el) => {
  el.addEventListener("click", () => {
    const target = el.dataset.nav;
    if (target === "flashcards") startFlashcards();
    else showScreen(target);
  });
});

/* ---------------------------------------------------------------------------
   初期表示
   リンクを開いたらすぐ問題を解けるように、ランダム10問のミックス練習を自動開始する。
   モードや問題数を変えたい場合はヘッダーの「ホーム」から選び直せる。
--------------------------------------------------------------------------- */
selectedMode = "random";
selectedCount = 10;
document.querySelector('.mode-card[data-mode="random"]').classList.add("selected");
document.querySelector('.count-card[data-count="10"]').classList.add("selected");
updateStartButton();
renderSpeedControls();
renderLevelControl();
renderHome();
startMixed(selectedMode, selectedCount);
